const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){menu.setAttribute('aria-expanded','false');nav.classList.remove('open');menu.focus()}});
const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealObserver.unobserve(e.target)}}),{threshold:.08,rootMargin:'0px 0px -6%'});
document.querySelectorAll('.reveal').forEach((e,i)=>{e.style.setProperty('--reveal-delay',`${Math.min(i%4,3)*70}ms`);revealObserver.observe(e)});
const tracked=[...document.querySelectorAll('main section[id]')];
const root=document.documentElement;
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
let ticking=false;function updateScroll(){const max=document.documentElement.scrollHeight-innerHeight;const page=max>0?scrollY/max:0;const heroProgress=Math.min(Math.max(scrollY/(innerHeight*.9),0),1);root.style.setProperty('--page-progress',page.toFixed(4));root.style.setProperty('--hero-progress',heroProgress.toFixed(4));document.querySelector('.scroll-progress').style.width=(page*100)+'%';document.querySelector('.site-header').classList.toggle('scrolled',scrollY>25);let active='home';tracked.forEach(s=>{if(s.getBoundingClientRect().top<200)active=s.id});if(active==='experience')active='achievements';nav.querySelectorAll('a').forEach(a=>{const selected=a.hash==='#'+active;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')});ticking=false}
addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(updateScroll);ticking=true}},{passive:true});updateScroll();
const portraitStage=document.querySelector('.portrait-stage');
if(!reduceMotion&&matchMedia('(pointer:fine)').matches){portraitStage.addEventListener('pointermove',e=>{const r=portraitStage.getBoundingClientRect();root.style.setProperty('--portrait-y',`${((e.clientX-r.left)/r.width-.5)*18}deg`);root.style.setProperty('--portrait-x',`${((e.clientY-r.top)/r.height-.5)*-12}deg`)});portraitStage.addEventListener('pointerleave',()=>{root.style.setProperty('--portrait-y','0deg');root.style.setProperty('--portrait-x','0deg')})}
document.querySelectorAll('.skill-card,.featured-project,.secondary-project').forEach(card=>{if(!reduceMotion&&matchMedia('(pointer:fine)').matches){card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect();card.style.setProperty('--tilt-x',`${((e.clientY-r.top)/r.height-.5)*-2.5}deg`);card.style.setProperty('--tilt-y',`${((e.clientX-r.left)/r.width-.5)*3.5}deg`)});card.addEventListener('pointerleave',()=>{card.style.removeProperty('--tilt-x');card.style.removeProperty('--tilt-y')})}});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{const selected=x===b;x.classList.toggle('selected',selected);x.setAttribute('aria-pressed',String(selected))});document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=b.dataset.filter!=='all'&&card.dataset.category!==b.dataset.filter;card.classList.add('visible')})}));
let previousFocus;
const openDialog=dialog=>{previousFocus=document.activeElement;dialog.showModal();document.body.style.overflow='hidden'};
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow='';previousFocus?.focus()})});
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const p=d.projects[Number(b.dataset.project)];document.querySelector('#project-detail').innerHTML=`<div class="eyebrow">${esc(p.type)}</div><h2 id="project-dialog-title">${esc(p.name)}</h2><p class="dialog-subtitle">${esc(p.subtitle)}</p><div class="tags">${tags(p.stack)}</div><h3>The problem</h3><p>${esc(p.problem)}</p><h3>My contribution</h3><p>${esc(p.role)}</p><h3>Key features</h3><ul>${p.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p class="future-scope"><strong>Future scope</strong><br>${esc(p.future)}</p>${safeUrl(p.url)?`<a class="button primary" href="${safeUrl(p.url)}" target="_blank" rel="noopener noreferrer">Visit website ↗</a>`:''}`;openDialog(document.querySelector('#project-dialog'))}));
const gallery=[{src:'assets/ceremony.jpg',alt:'Nasrin receiving her degree on stage at the University of Calicut graduation ceremony',caption:'Graduation ceremony · University of Calicut'},{src:'assets/award.jpg',alt:'Nasrin receiving her degree alongside university officials',caption:'A proud milestone · Degree presentation'},{src:'assets/graduation.jpg',alt:'Nasrin outdoors in graduation attire',caption:'Graduation day · A new beginning'}];
let imageIndex=0;const renderImage=()=>{const g=gallery[imageIndex];document.querySelector('#lightbox-image').src=g.src;document.querySelector('#lightbox-image').alt=g.alt;document.querySelector('#lightbox-caption').textContent=`${g.caption} — ${imageIndex+1} / ${gallery.length}`};
document.querySelectorAll('[data-gallery]').forEach(b=>b.addEventListener('click',()=>{imageIndex=Number(b.dataset.gallery);renderImage();openDialog(document.querySelector('#image-dialog'))}));
const stepImage=dir=>{imageIndex=(imageIndex+dir+gallery.length)%gallery.length;renderImage()};document.querySelector('.gallery-prev').addEventListener('click',()=>stepImage(-1));document.querySelector('.gallery-next').addEventListener('click',()=>stepImage(1));document.querySelector('#image-dialog').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();stepImage(-1)}if(e.key==='ArrowRight'){e.preventDefault();stepImage(1)}});
const socials=[['LinkedIn',d.linkedin],['GitHub',d.github]].filter(([,url])=>safeUrl(url));document.querySelector('#social-links').innerHTML=socials.map(([name,url])=>`<a class="text-link" href="${safeUrl(url)}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`).join('');
if(d.certificates.length){document.querySelector('.certification-slot').hidden=true;document.querySelector('#certificate-gallery').innerHTML=d.certificates.map((c,i)=>`<button class="certificate-card" data-cert="${i}"><img src="${esc(c.image)}" alt="${esc(c.title)}" loading="lazy"><strong>${esc(c.title)}</strong><span>${esc(c.issuer)}${c.date?' · '+esc(c.date):''}</span></button>`).join('');document.querySelectorAll('[data-cert]').forEach(b=>b.addEventListener('click',()=>{const c=d.certificates[Number(b.dataset.cert)];gallery.push({src:c.image,alt:c.title,caption:[c.title,c.issuer,c.date].filter(Boolean).join(' · ')});imageIndex=gallery.length-1;renderImage();openDialog(document.querySelector('#image-dialog'))}))}
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;for(const input of form.querySelectorAll('input,textarea')){input.setCustomValidity(input.value.trim()?'':'Please complete this field.');input.addEventListener('input',()=>input.setCustomValidity(''),{once:true})}if(!form.reportValidity())return;const values=new FormData(form);const body=`Hello Nasrin,\n\n${values.get('message').trim()}\n\nFrom: ${values.get('name').trim()}\nEmail: ${values.get('email').trim()}`;location.href=`mailto:${d.email}?subject=${encodeURIComponent(values.get('subject').trim())}&body=${encodeURIComponent(body)}`;document.querySelector('#form-status').textContent='Your email draft is ready to open. Send it from your email app. If no app opens, email me directly using the address shown.'});
